  expect(await ui.delegate(pg_vic, {"user": "uma", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.periodAction(pg_uma, "2026-04", "soft-close")).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.reassign(pg_vic, c_ben_0, "Ada")).toBe(true);
  expect(await ui.addPatron(pg_vic, p_ben, "Ada")).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.bulkGrade(pg_vic, [p_ben, p_ada], {"grade": "C"})).toBe(2);
  expect(await ui.statement(pg_vic, p_ben)).toBe(true);
  expect(await ui.editPerson(pg_vic, p_ben, {"terms": ""})).toBe(true);
  expect(await ui.addProof(pg_vic, c_ben_0)).toBe(true);
  expect(await ui.editPerson(pg_vic, p_cam, {"terms": "3"})).toBe(true);
  expect(await ui.claimEditOpen(pg_vic, c_ben_0)).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.claimEditOpen(pg_wes, c_ben_0)).toBe(false);
  await ui.refresh(pg_vic);
